import React, { useState } from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import Header from "./components/Header";
import CartDrawer from "./components/CartDrawer";
import Portfolio from "./pages/Portfolio";
import Home from "./pages/Home";
import Menu from "./pages/Menu";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Checkout from "./pages/Checkout";
import OrderTracking from "./pages/OrderTracking";
import MyOrders from "./pages/MyOrders";
import Admin from "./pages/Admin";

export default function App() {
  const [cartOpen, setCartOpen] = useState(false);

  return (
    <>
      <Routes>
        <Route path="/" element={<Portfolio />} />

        <Route
          path="/food/*"
          element={
            <>
              <Header onCartClick={() => setCartOpen(true)} />
              <Routes>
                <Route index element={<Home />} />
                <Route path="menu" element={<Menu />} />
                <Route path="login" element={<Login />} />
                <Route path="register" element={<Register />} />
                <Route path="checkout" element={<Checkout />} />
                <Route path="orders" element={<MyOrders />} />
                <Route path="orders/:orderId" element={<OrderTracking />} />
                <Route path="admin" element={<Admin />} />
              </Routes>
              <FoodFooter />
              {cartOpen && <CartDrawer onClose={() => setCartOpen(false)} />}
            </>
          }
        />

        {/* Keep direct old URLs working. */}
        <Route path="/menu" element={<Navigate to="/food/menu" replace />} />
        <Route path="/login" element={<Navigate to="/food/login" replace />} />
        <Route path="/register" element={<Navigate to="/food/register" replace />} />
        <Route path="/checkout" element={<Navigate to="/food/checkout" replace />} />
        <Route path="/orders" element={<Navigate to="/food/orders" replace />} />
        <Route path="/admin" element={<Navigate to="/food/admin" replace />} />
      </Routes>
    </>
  );
}

function FoodFooter() {
  return (
    <footer style={{ borderTop: "1px solid var(--border)", marginTop: 20, background: "var(--night)" }}>
      <div className="container" style={{ padding: "30px 24px", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
        <div className="disp-i" style={{ color: "var(--leaf-deep)", fontWeight: 600, fontSize: 15 }}>
          Healthy Food
        </div>
        <div className="eyebrow" style={{ color: "var(--ink-faint)" }}>© {new Date().getFullYear()} · Fresh, tracked, delivered</div>
      </div>
    </footer>
  );
}
